insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-189', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Between lithium and beryllium, beryllium has the greater first ionisation enthalpy because of its', '["lower Zeff and 2p¹ configuration","higher Zeff and 2s² configuration","much larger radius","noble-gas core of argon"]'::jsonb, 1, 'Be is smaller, has one extra proton and a filled 2s pair, so IE₁(Be) > IE₁(Li).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
