insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-190', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'The second ionisation enthalpy of sodium is very large because the second electron must be taken from the', '["3s¹ valence orbital","neon-like 2p⁶ core","4s subshell","empty 3d set"]'::jsonb, 1, 'After loss of 3s¹, Na⁺ is isoelectronic with Ne; breaking that closed shell requires a large IE₂.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
